$('#dialog-close').onclick=()=>$('#dialog').close();
function showSetup(){document.body.dataset.screen='setup'; $('#setup').hidden=false;$('#game').hidden=true;$('#export').hidden=!state;$('#new-scenario').hidden=!state;$('#resume-company').hidden=!state;renderSetup();}
function renderSetup(){const cap=P.capacity(setupCount),rec=P.recommend(setupCount);$('#setup').innerHTML=`<div class="setup-hero"><div><div class="eyebrow">BUILD IT. BREAK IT. UNDERSTAND IT.</div><h1>公司還沒開張。<br>網路，由你從零開始。</h1><p>先選公司規模，理解架構，再一步一步部署 Cisco 網路。營運後，面對同仁亂接線、接點氧化、電腦老化，學會找證據和修復。</p><div class="scope-note">電腦網購 → 自選機房 → 庫存上架 → Cisco 教學 → 營運維護<br>電腦版 · 上帝視角直接管理 · 無套件安裝需求</div></div><div class="size-box"><label for="company-size">先告訴我，公司預計有多少人？</label><div class="size-input"><input id="company-size" type="number" min="1" max="10000" value="${setupCount}"><span>位員工</span></div><div class="size-presets">${[12,80,500,3000].map(n=>`<button data-size="${n}" class="${n===setupCount?'selected':''}">${fmt(n)} 人</button>`).join('')}</div><div class="size-summary">有線端點 ${fmt(cap.endpointDemand)} 個 + 20% 預留 ${fmt(cap.sparePorts)} 埠<br>規劃 ${fmt(cap.requiredPorts)} 埠，至少 ${fmt(cap.accessSwitches)} 台 48 埠接入交換器。</div></div></div><div class="setup-section-head"><h2>依規模挑選你的網路骨架。</h2><p>人數是起點；實際設計仍需考慮樓棟、頻寬、安全及可用性。</p></div><div class="plan-grid">${P.plans.map((p,i)=>`<article class="plan-card ${p.id===rec.id?'recommended':''}"><div class="plan-number">0${i+1}</div>${p.id===rec.id?'<span class="recommend-badge">依目前規模推薦</span>':''}<h3>${p.name}</h3><p>${p.summary}</p><div class="mini-topology">${topologyText(p.id).join('<br>↓<br>')}</div><ul>${p.reasons.map(r=>`<li>${r}</li>`).join('')}</ul><div class="plan-note">${p.id===rec.id?`適合這次 ${fmt(setupCount)} 人公司的教學起點。`:`可自由試作；目前 ${fmt(setupCount)} 人不在本方案建議範圍，請留意規模與架構差異。`}</div><button class="${p.id===rec.id?'primary':'secondary'} wide" data-choose-plan="${p.id}">選擇此架構，開始從零建置 →</button></article>`).join('')}</div><p class="scope-note">${cap.assumption} 設備價格、壽命與故障機率均為遊戲模型。架構以一個代表區域教學，其他區域按容量計算。</p>`;
 $('#company-size').onchange=e=>{const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>10000){toast('請輸入 1–10,000 的整數。');e.target.value=setupCount;return;}setupCount=n;renderSetup();};$$('[data-size]').forEach(b=>b.onclick=()=>{setupCount=+b.dataset.size;renderSetup();});$$('[data-choose-plan]').forEach(b=>b.onclick=()=>startScenario(b.dataset.choosePlan));$('#resume-company')?.addEventListener('click',showGame);}
function topologyText(id){return id==='small'?['ISP / Cisco ISR','安全閘道','單台接入交換器','員工工作站']:id==='collapsed'?['ISP / 安全邊界','折疊核心 A + B','各辦公區接入交換器','員工工作站']:['ISP / 安全邊界','骨幹核心 A + B','區域彙聚 A + B','各區接入 → 工作站'];}
function startScenario(planId){if(P.recommend(setupCount).id!==planId){dialog(`<span class="eyebrow">ARCHITECTURE REVIEW</span><h2>這是一次刻意的架構實驗。</h2><p>${P.getPlan(planId).name} 不是目前人數的建議方案。你仍可以學習它的設備角色，但能否用在真實公司，需要額外的樓棟、頻寬和故障範圍評估。</p><button id="confirm-plan" class="primary">了解差異，開始此架構</button>`);$('#confirm-plan').onclick=()=>{$('#dialog').close();createCompany(planId);};}else createCompany(planId);}
function createCompany(planId){state=S.create({employees:setupCount,planId,seed:20261109});ui();view='field';paused=false;clock=0;shopRackCount=0;shopPage=0;currentRack=null;rackTarget=null;selectedAsset=null;keys.clear();drag=null;initConsoles();showGame();save();toast('新公司已準備好。第一步：依架構採購設備。');}
function showGame(){document.body.dataset.screen='game';ui();initConsoles();$('#setup').hidden=true;$('#game').hidden=false;$('#export').hidden=false;$('#new-scenario').hidden=false;$('#resume-company').hidden=true;render();resize();if(ui().camera&&Number.isFinite(ui().camera.x)&&Number.isFinite(ui().camera.y)){camera={...ui().camera};zoom=Math.max(.16,Math.min(1.6,Number(ui().zoom)||.62));}else{camera={x:550,y:1200};zoom=.62;}}
const checklistKeys={purchase:'purchased',power:'powered',wan:'cabled',cable:'cabled',vlans:'configured',trunk:'configured',address:'configured',save:'saved',test:'tested',operate:'operating'};
function configReady(){return state.milestones.configured&&!S.status(state).configurationProblems.length&&consolesReady();}
function currentStage(){const m=state.milestones;if(!m.purchased)return 'purchase';if(!F.ensure(state).built)return 'site';if(R.next(state,P.getPlan(state.planId)))return 'rack';if(!m.powered)return 'power';if(!m.cabled)return 'cable';if(!configReady())return 'configure';if(!m.saved)return 'save';if(!m.tested&&!m.operating)return 'test';if(!m.operating)return 'operate';return 'maintain';}
function stageInfo(stage){const steps=P.steps(state.planId);return stage==='cable'?{...steps.find(s=>s.id==='cable'),title:'05–06 · 外網與辦公區配線'}:stage==='configure'?{...steps.find(s=>s.id==='vlans'),title:'07–09 · VLAN、上聯與閘道',instruction:'先完成每台交換器的指令教學，再切換「地址與驗證」套用閘道與 DHCP，最後保存全部組態。'}:steps.find(s=>s.id===stage)||steps.at(-1);}
function stepDone(step){if(step.id==='site')return F.ensure(state).built;if(step.id==='rack')return state.milestones.purchased&&!R.next(state,P.getPlan(state.planId));return ['vlans','trunk','address'].includes(step.id)?configReady():state.milestones[checklistKeys[step.id]];}
function render(){if(!state)return;const p=P.getPlan(state.planId),st=S.status(state),cap=state.capacity;$('#company-title').textContent=`${fmt(state.employees)} 人公司 · ${state.milestones.operating?'網路維運':'從零建置'}`;$('#plan-description').textContent=p.name+' ｜ '+(state.planId===P.recommend(state.employees).id?'本次推薦架構':'自行選擇的架構實驗');$('#scene-label').textContent=`${fmt(state.employees)} STAFF / ${state.sampledEndpoints} REPRESENTATIVE WORKSTATIONS`;$('#metrics').innerHTML=`<div class="metric"><small>建置／維修預算</small><strong>NT$ ${fmt(state.budget)}</strong><em>遊戲預算</em></div><div class="metric"><small>線上／規劃員工</small><strong class="${st.affected?'bad':'good'}">${fmt(st.online)} / ${fmt(st.total)}</strong><em>${st.affected?`${fmt(st.affected)} 人受影響`:'模型連線正常'}</em></div><div class="metric"><small>資料埠規劃</small><strong>${fmt(cap.installedPorts)}</strong><em>${fmt(cap.accessSwitches)} 台接入設備</em></div><div class="metric"><small>目前待處理事件</small><strong class="${st.activeIncidents?'amber':'good'}">${st.activeIncidents}</strong><em>已修復 ${state.completedRepairs} 件</em></div>`;$('#incident-count').textContent=st.activeIncidents;$('#pause').textContent=paused?'繼續':'暫停';$('#game-clock').textContent=`第 ${Math.floor(state.elapsedMinutes/S.YEAR)+1} 年 · 第 ${Math.floor(state.elapsedMinutes%S.YEAR/S.DAY)+1} 日 · ${String(Math.floor(state.elapsedMinutes%1440/60)).padStart(2,'0')}:${String(Math.floor(state.elapsedMinutes%60)).padStart(2,'0')}`;renderGuide();$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#field-view').hidden=view!=='field';$('#data-view').hidden=view==='field';if(view!=='field')renderData();renderLog();if(selectedAsset)renderAssetPanel();scheduleSave();}
function renderGuide(){const stage=currentStage(),m=state.milestones,st=S.status(state),info=stageInfo(stage);if(stage==='maintain'){$('#guide').innerHTML=`<div class="guide-phase">OPERATIONS / LEARN BY DIAGNOSING</div><h2>${st.activeIncidents?'先蒐證，再動手。':'網路建好，工作才開始。'}</h2><p>${st.message}</p><div class="why">線材會彎折、網孔會氧化，電腦也有壽命。短暫恢復 UP 不代表間歇故障已修好。</div><button class="primary wide" id="open-incidents">查看事件與報修 →</button><div class="panel-buttons"><button class="secondary" id="practice">安排一個故障練習</button><button class="secondary" id="advance-day">快轉 1 遊戲日</button><button class="secondary" id="advance-month">快轉 30 遊戲日</button><button class="secondary" id="advance-year">快轉 1 年</button><button class="secondary" id="verify-network">重新驗收連線</button></div><p class="scope-note">電腦預期 6 年、線材 15 年、網孔 20 年。倍率只加速遊戲日曆，不會縮短設備年限。未儲存的正確 running-config 仍可上線，正式驗收才要求存檔。</p><p class="scope-note">${state.scope}</p>`;$('#open-incidents').onclick=()=>setView('incidents');$('#practice').onclick=showPractice;$('#advance-day').onclick=()=>act(()=>S.tick(state,1440));$('#advance-month').onclick=()=>act(()=>S.tick(state,30*S.DAY));$('#advance-year').onclick=()=>{dialog('<h2>推進 1 個遊戲年？</h2><p>設備會累計 1 年使用時間。電腦預期 6 年、線材 15 年、網孔 20 年；到期與其他故障仍需診斷後維修。</p><button class="primary" id="confirm-year">確認快轉 1 年</button>');$('#confirm-year').onclick=()=>{$('#dialog').close();act(()=>S.tick(state,S.YEAR));};};$('#verify-network').onclick=testNetwork;return;}
 const actionLabel={purchase:'使用管理電腦開啟網購',site:'比較機房位置與推薦地點',rack:'選擇機櫃與 U 位',power:'開啟 UPS / PDU 電源',cable:'依下方提示接線',configure:'開啟交換器 Console',save:'示範儲存全部設備組態',test:'執行工作站連線驗收',operate:'讓公司正式開始營運'}[stage];$('#guide').innerHTML=`<div class="guide-phase">GUIDED BUILD / ${stage.toUpperCase()}</div><h2>${info.title}</h2><p>${info.instruction}</p><div class="why"><b>為什麼要做？</b><br>${info.why}</div>${stage==='rack'?`<div class="rack-next">尚有 ${R.available(state,P.getPlan(state.planId)).length} 台設備在庫存<br>先選機櫃 → 點空 U 位 → 選庫存設備 → 確認上架</div>`:''}${stage==='cable'?wireControls():`<button class="primary wide" id="guide-action">${actionLabel} →</button>`}${stage==='purchase'?`<p class="scope-note">本次採購 NT$ ${fmt(F.quote(state).total)}，含 ${fmt(state.employees)} 個工作站與 ${fmt(state.capacity.accessSwitches)} 台接入交換器。</p>`:''}<div class="build-progress"><span>${P.steps(state.planId).filter(stepDone).length} / ${P.steps(state.planId).length} 步驟完成</span><button class="secondary" id="show-steps">建置流程</button></div>`;
 $('#show-steps').onclick=()=>dialog('<h2>建置流程</h2><ol class="steps-list">'+P.steps(state.planId).map(s=>'<li><b>'+s.title+'</b><span>'+s.instruction+'</span></li>').join('')+'</ol>');if(stage==='cable')bindWire();else $('#guide-action').onclick=()=>{if(stage==='purchase')openComputer();if(stage==='site')openSiteSelection();if(stage==='rack')openRackDirectory();if(stage==='power')act(()=>S.power(state));if(stage==='configure')openConsole();if(stage==='save')saveAll();if(stage==='test')testNetwork();if(stage==='operate')act(()=>S.start(state));};}
function openComputer(){dialog(`<div class="computer-window"><div class="computer-title">資訊管理電腦 · ADMIN-PC</div><div class="computer-desktop"><div class="pc-network"><i class="led green"></i> 行動網路已連線 · 可先採購公司網路設備</div><h2>準備開始建置。</h2><p>這台管理電腦已提供獨立網路，請先開瀏覽器購買設備。</p><button id="pc-browser" class="desktop-shortcut"><span>◎</span><b>開啟瀏覽器</b><small>網路設備採購網站</small></button>${state.milestones.purchased?'<button id="pc-orders" class="secondary">查看訂單與到貨庫存</button>':''}</div></div>`);$('#dialog').className='computer-dialog';$('#pc-browser').onclick=()=>{shopPage=0;openShop();};$('#pc-orders')?.addEventListener('click',openShop);}
function openShop(){const f=F.ensure(state);shopRackCount=state.milestones.purchased?f.rackCount:shopRackCount||f.rackCount;const q=F.quote(state,shopRackCount),items=F.catalog(state,shopRackCount),pages=Math.ceil(items.length/6);shopPage=Math.min(shopPage,pages-1);dialog(`<div class="shop-browser"><div class="browser-address">←　↻　🔒 procurement.local / network-equipment <span>遊戲內採購網站</span></div><div class="shop-head"><div><span class="eyebrow">NET SUPPLY / BUSINESS PROCUREMENT</span><h2>${state.milestones.purchased?'訂單已到貨':'公司網路設備採購'}</h2></div><span>ADMIN-PC · 行動網路連線</span></div>${state.milestones.purchased?`<div class="order-receipt"><span class="receipt-icon">✓</span><h3>${ui().procurement?.orderId||'既有訂單'} · 到貨完成</h3><p>${f.rackCount} 座空機櫃及建置設備已入庫。</p><p>接著由你決定機房的位置，並選擇每台設備要放在哪座機櫃、哪個 U 位。</p><button id="receipt-next" class="primary">${f.built?'查看機房與機櫃':'選擇機房位置'} →</button><button id="receipt-close" class="secondary">返回公司畫面</button></div>`:`<div class="shop-layout"><div class="shop-products"><p>依 ${fmt(state.employees)} 人與架構計算全公司清單；本關庫存操作代表機房，其餘區域採批次部署。</p><table><thead><tr><th>品項</th><th>數量</th><th>單價</th></tr></thead><tbody>${items.slice(shopPage*6,shopPage*6+6).map(e=>`<tr><td><b>${esc(e.name)}</b><small>${esc(e.model)}</small></td><td>${fmt(e.quantity)}</td><td>NT$ ${fmt(e.unitPrice)}</td></tr>`).join('')}</tbody></table><div class="pagination"><button id="shop-prev" class="secondary" ${shopPage===0?'disabled':''}>← 上一頁</button><span>${shopPage+1} / ${pages}</span><button id="shop-next" class="secondary" ${shopPage===pages-1?'disabled':''}>下一頁 →</button></div></div><aside class="shop-cart"><h3>購物車</h3><label>42U 機櫃數量<select id="shop-rack-count">${Array.from({length:10},(_,i)=>i+3).map(n=>`<option value="${n}" ${n===shopRackCount?'selected':''}>${n} 座機櫃</option>`).join('')}</select></label><p>機櫃可分工放置邊界、核心與接入設備，也可以保留空櫃擴充。</p><div class="shop-total"><small>本次訂單合計</small><b>NT$ ${fmt(q.total)}</b><span>目前預算 NT$ ${fmt(state.budget)}</span></div><p>機房建設費會依你選擇的地點另外計算。</p><button id="shop-checkout" class="primary wide">確認清單並下單</button></aside></div>`}</div>`);$('#dialog').className='shop-dialog';if(state.milestones.purchased){$('#receipt-next').onclick=()=>f.built?openRackDirectory():openSiteSelection();$('#receipt-close').onclick=()=>$('#dialog').close();return;}$('#shop-rack-count').onchange=e=>{shopRackCount=+e.target.value;openShop();};$('#shop-prev').onclick=()=>{shopPage--;openShop();};$('#shop-next').onclick=()=>{shopPage++;openShop();};$('#shop-checkout').onclick=()=>{const r=act(()=>F.order(state,shopRackCount));if(r.ok)openShop();};}
function openSiteSelection(){if(!state?.milestones.purchased)return openComputer();const f=F.ensure(state);if(f.built)return openRackDirectory();const selected=F.sites.find(s=>s.id===f.siteId);dialog(`<span class="eyebrow">PLAN YOUR SERVER ROOM</span><h2>機房蓋在哪裡，由你決定。</h2><p>目前已購買 ${f.rackCount} 座機櫃。推薦 A 區，但你可以比較成本與風險後選擇。</p><div class="site-grid">${F.sites.map(s=>`<article class="site-card ${s.id===f.siteId?'chosen':''}">${s.recommended?'<span class="recommend-badge">推薦位置</span>':''}<div class="site-plan"><svg viewBox="0 0 160 95" aria-label="${esc(s.name)}位置"><rect x="4" y="4" width="152" height="87" rx="4" fill="#dfe8d7"/><rect x="75" y="9" width="74" height="76" rx="3" fill="#eddec2"/><rect x="${10}" y="${s.y/20+6}" width="55" height="${Math.min(s.d/20,70)}" rx="3" fill="#659c88"/><text x="110" y="50" text-anchor="middle" fill="#967c5e" font-size="11">辦公區</text></svg></div><h3>${esc(s.name)}</h3><div class="site-cost">NT$ ${fmt(s.cost)} <small>最多 ${s.capacity} 座機櫃</small></div><ul>${s.advantages.map(t=>`<li>${t}</li>`).join('')}</ul><p>${s.tradeoff}</p><button class="${s.id===f.siteId?'primary':'secondary'} wide" data-select-site="${s.id}" ${f.rackCount>s.capacity?'disabled':''}>${f.rackCount>s.capacity?'空間不足':s.id===f.siteId?'已選擇此位置':'選擇此位置'}</button></article>`).join('')}</div><div class="site-confirm"><span>${selected?`已選 ${selected.name} · 建設費 NT$ ${fmt(selected.cost)}`:'整層空間已擴大；選位置後才建設與扣款'}</span><button id="build-server-room" class="primary" ${!selected||state.budget<selected.cost?'disabled':''}>在此建設機房 →</button></div>`);$('#dialog').className='site-dialog';$$('[data-select-site]').forEach(b=>b.onclick=()=>{const r=act(()=>F.selectSite(state,b.dataset.selectSite));if(r.ok)openSiteSelection();});$('#build-server-room').onclick=()=>{const r=act(()=>F.build(state));if(r.ok){$('#dialog').close();focusRoom();}};}
function openRackDirectory(){if(!state?.milestones.purchased)return openComputer();if(!F.ensure(state).built)return openSiteSelection();const plan=P.getPlan(state.planId),racks=F.rackPositions(state);dialog(`<span class="eyebrow">SERVER ROOM / SELECT A CABINET</span><h2>先選一座機櫃，再選 U 位。</h2><p>${F.sites.find(s=>s.id===F.ensure(state).siteId).name} · ${racks.length} 座機櫃 · 庫存尚有 ${R.available(state,plan).length} 台代表設備</p><div class="rack-directory">${racks.map(r=>{const installed=R.placements(state,plan,r.id),used=installed.reduce((n,e)=>n+e.units,0);return `<button class="cabinet-card" data-enter-rack="${r.id}"><span class="cabinet-icon"><i></i><i></i><i></i><i></i><i></i></span><strong>${r.id}</strong><span>${installed.length} 台設備 · ${used} / 42U 已使用</span><b>選擇這座機櫃 →</b></button>`;}).join('')}</div><button id="room-back" class="secondary">返回 3D 機房</button>`);$('#dialog').className='room-dialog';$$('[data-enter-rack]').forEach(b=>b.onclick=()=>{rackMode='details';rackTarget=null;openRack(b.dataset.enterRack);});$('#room-back').onclick=()=>{$('#dialog').close();focusRoom();};}
function openRack(id=currentRack){if(!F.ensure(state).built)return openSiteSelection();const racks=F.rackPositions(state);if(!id||!racks.some(r=>r.id===id))return openRackDirectory();currentRack=id;const plan=P.getPlan(state.planId),all=R.equipment(state,plan),installed=R.placements(state,plan,id),stock=R.available(state,plan),chosen=all.find(e=>e.id===rackTarget),entry=installed.find(e=>e.id===rackTarget),used=installed.reduce((n,e)=>n+e.units,0),valid=chosen?R.validate(state,plan,chosen.id,id,rackSlot):null;inventoryPage=Math.min(inventoryPage,Math.max(0,Math.ceil(stock.length/6)-1));
dialog(`<div class="rack-title"><span class="eyebrow">42U CABINET / CLICK A SLOT / OPEN INVENTORY</span><h2>${id} · ${rackMode==='inventory'?'U'+rackSlot+' 上架庫存設備':'選擇分隔，再放入設備'}</h2></div><div class="rack-layout"><div class="rack-elevation"><div class="rack-brand"><b>NET / OPS</b><span>${id} · 42U</span></div><div class="rack-rails">${Array.from({length:42},(_,i)=>`<button class="rack-u ${rackMode==='inventory'&&rackSlot===42-i?'slot-selected':''}" data-rack-u="${42-i}" title="選擇 U${42-i}，開啟庫存"><span>${42-i}</span><i></i><i></i></button>`).join('')}${installed.map(e=>`<button class="rack-device role-${e.role} ${e.id===rackTarget?'selected':''}" data-rack-equipment="${e.id}" style="top:${(42-e.topU)/42*100}%;height:${e.units/42*100}%" title="${esc(e.label)} · U${e.topU}"><span class="mount-ear">●</span><b>${esc(e.id.toUpperCase())}</b><span class="faceplate-ports"></span>${!['manager','patch'].includes(e.role)?`<i class="led ${R.indicator(state,e.id,S.status(state)).color}"></i>`:''}<span class="mount-ear">●</span></button>`).join('')}</div><div class="rack-bottom"><span>LOCK ●</span><span>${used}U USED / ${42-used}U FREE</span></div><div class="rack-pdu">PDU<br>│<br>●<br>│<br>●<br>│<br>●<br>│<br>●</div></div><aside class="rack-controls">${rackMode==='inventory'?`<div class="inventory-heading"><h3>庫存設備</h3><span>${stock.length} 台本區設備可用 · ${id} / U${rackSlot}</span></div><div class="stock-grid">${stock.slice(inventoryPage*6,inventoryPage*6+6).map(e=>`<button data-stock-id="${e.id}" class="stock-item ${e.id===rackTarget?'selected':''}"><b>${esc(e.label)}</b><span>${esc(e.model)}</span><small>${e.units}U · 點選預覽</small></button>`).join('')}${!stock.length?'<p>所有代表設備都已上架。</p>':''}</div><div class="pagination"><button id="stock-prev" class="secondary" ${inventoryPage===0?'disabled':''}>←</button><span>${inventoryPage+1} / ${Math.max(1,Math.ceil(stock.length/6))}</span><button id="stock-next" class="secondary" ${(inventoryPage+1)*6>=stock.length?'disabled':''}>→</button></div><div class="stock-selection">${chosen?`<b>${esc(chosen.label)} · ${chosen.units}U</b><p>放置於 ${id} · U${rackSlot}${chosen.units>1?'–U'+(rackSlot-chosen.units+1):''}</p><p class="${valid.ok?'good':'bad'}">${valid.message}</p>${chosen.role==='ups'&&rackSlot>6?'<p>建議將較重的 UPS 放在底部 U6 以下。</p>':''}`:'先從庫存選擇一台設備。'}</div><button id="install-device" class="primary wide" ${!chosen||!valid?.ok?'disabled':''}>確認上架到選定 U 位</button>`:`<span class="eyebrow">${entry?'INSTALLED EQUIPMENT':'SELECT A FREE SLOT'}</span><h3>${entry?esc(entry.label):'點選左側空白 U 位'}</h3><p>${entry?esc(entry.model):'每一個分隔代表 1U。點擊空槽後，右側會打開庫存，選擇設備再確認上架。'}</p>${entry?`<div class="rack-position">U${entry.topU}${entry.units>1?' – U'+entry.bottomU:''}<small>${entry.units}U · ${id}</small></div><span class="status-badge" data-status="${R.indicator(state,entry.id,S.status(state)).color}"><i></i>${R.indicator(state,entry.id,S.status(state)).color==='red'?'異常':'正常'}</span>`:''}<div class="rack-note">本櫃已使用 ${used} / 42U；可把不同設備分配到其他機櫃。設備需有足夠連續空槽，已上架的設備會從庫存移除。</div>${entry&&state.assets.some(a=>a.id===entry.id)?'<button class="secondary wide" id="rack-manage-asset">直接管理這台設備</button>':''}`}<div class="rack-navigation"><button class="secondary wide" id="choose-other-rack">選其他機櫃</button><button class="secondary wide" id="rack-done">返回 3D 機房</button></div></aside></div>`);$('#dialog').className='rack-dialog';$$('[data-rack-u]').forEach(b=>b.onclick=()=>{rackSlot=+b.dataset.rackU;rackMode='inventory';rackTarget=null;inventoryPage=0;openRack(id);});$$('[data-rack-equipment]').forEach(b=>b.onclick=()=>{rackTarget=b.dataset.rackEquipment;rackMode='details';openRack(id);});$$('[data-stock-id]').forEach(b=>b.onclick=()=>{rackTarget=b.dataset.stockId;openRack(id);});$('#stock-prev')?.addEventListener('click',()=>{inventoryPage--;openRack(id);});$('#stock-next')?.addEventListener('click',()=>{inventoryPage++;openRack(id);});$('#install-device')?.addEventListener('click',()=>{const r=act(()=>R.place(state,plan,rackTarget,id,rackSlot));if(r.ok)rackMode='details';openRack(id);});$('#rack-manage-asset')?.addEventListener('click',()=>{$('#dialog').close();selectAsset(entry.id);});$('#choose-other-rack').onclick=openRackDirectory;$('#rack-done').onclick=()=>{$('#dialog').close();focusRoom();render();};}

function act(fn){try{const r=fn();toast(r.message);render();return r;}catch(e){toast(e.message);return{ok:false,message:e.message};}}
function links(){const l=[['ISP','edge'],['edge','firewall']];if(state.planId==='small')l.push(['firewall','access-1']);else{l.push(['firewall','core-1']);if(state.planId==='three-tier')l.push(['core-1','dist-1'],['dist-1','access-1']);else l.push(['core-1','access-1']);}l.push(['access-1','jack-01'],['jack-01','pc-01']);return l.map(([from,to],i)=>({id:'link-'+i,from,to}));}
function displayName(id){if(id==='ISP')return 'ISP 交接';if(id==='jack-01')return '牆面插座 J1';if(id==='pc-01')return '工作站 PC-01';return P.getPlan(state.planId).equipment.find(e=>e.id===id)?.label||id;}
function wireControls(){const pending=links().find(l=>!ui().wires.includes(l.id));if(!pending)return '<p>接線已完成。</p>';return `<div class="wire-progress">${ui().wires.length} / ${links().length} 段</div><div class="wire-instruction">${ui().pendingWire?'已拿起第一端，請點正確的另一端。':'先點第一個設備，再點要連接的另一端。'}<button class="${ui().pendingWire===pending.from?'selected':''}" data-wire-end="${pending.from}">${displayName(pending.from)} · ${wirePort(pending.from,pending.to)}</button><div style="text-align:center">↓ Cat6 ／指定上聯</div><button data-wire-end="${pending.to}">${displayName(pending.to)} · ${wirePort(pending.to,pending.from)}</button></div><p class="scope-note">圖上連接第一個代表區域，其餘辦公區按容量展開。備機僅上架，未設定 HA 不會自動接手。</p><button class="secondary wide" id="cancel-wire">取消這次選取</button>`;}
function wirePort(id,peer){if(id==='edge')return peer==='ISP'?'WAN':'LAN';if(id==='firewall')return peer==='edge'?'WAN':'LAN';if(id==='jack-01')return 'J1';if(id==='pc-01')return 'eth0';if(id==='ISP')return 'GE0';if(id==='core-1')return peer==='firewall'?'Gi1/0/23':'Gi1/0/24';if(id==='dist-1')return peer==='core-1'?'Gi1/0/23':'Gi1/0/24';return peer==='jack-01'?'Gi1/0/1':'Gi1/0/24';}
function bindWire(){$$('[data-wire-end]').forEach(b=>b.onclick=()=>{const l=links().find(l=>!ui().wires.includes(l.id));if(!ui().pendingWire){if(b.dataset.wireEnd!==l.from)return toast('先從上方第一個設備開始。');ui().pendingWire=l.from;}else{if(b.dataset.wireEnd!==l.to)return toast('另一端應接到 '+displayName(l.to));ui().wires.push(l.id);ui().pendingWire=null;if(ui().wires.length===links().length){act(()=>S.cable(state));return;}}render();});$('#cancel-wire').onclick=()=>{ui().pendingWire=null;render();};}
function setView(next){if(view!==next)dataPage=0;view=next;selectedAsset=null;$('#asset-panel').hidden=true;render();if(view==='field')resize();}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function renderLog(){$('#event-log').innerHTML='<b>最新事件</b>'+state.logs.filter(l=>!l.message.startsWith('營運推進')||!l.message.includes('0 件新事件')).slice(-1).reverse().map(l=>`<div><time>Y${Math.floor(l.minute/S.YEAR)+1} D${Math.floor(l.minute%S.YEAR/S.DAY)+1} ${String(Math.floor(l.minute%1440/60)).padStart(2,'0')}:${String(Math.floor(l.minute%60)).padStart(2,'0')}</time>${esc(l.message)}</div>`).join('');}
function pager(total,size){const pages=Math.max(1,Math.ceil(total/size));dataPage=Math.min(dataPage,pages-1);return `<div class="pagination"><button id="page-prev" class="secondary" ${dataPage===0?'disabled':''}>← 上一頁</button><span>${dataPage+1} / ${pages} 頁 · 共 ${total} 筆</span><button id="page-next" class="secondary" ${dataPage===pages-1?'disabled':''}>下一頁 →</button></div>`;}
function bindPager(){for(const [id,delta] of [['page-prev',-1],['page-next',1]])$('#'+id)?.addEventListener('click',()=>{dataPage+=delta;renderData();});bindVisits();}
function renderData(){const st=S.status(state),size=Math.max(3,Math.min(10,Math.floor(($('#data-view').clientHeight-175)/43)));
 if(view==='architecture'){const p=P.getPlan(state.planId),c=state.capacity;$('#data-view').innerHTML=`<div class="data-panel"><div class="data-title"><h2>${p.name}</h2><div class="button-row">${['架構與容量','設備清單','規劃說明'].map((t,i)=>`<button class="${i===architecturePage?'primary':'secondary'}" data-arch-page="${i}">${t}</button>`).join('')}</div></div>${architecturePage===0?`<p>${p.summary}</p><div class="architecture-chain">${topologyText(p.id).map(s=>`<span>${s}</span>`).join(' → ')}</div><div class="capacity-grid"><div><small>工作站端點</small><b>${fmt(c.endpointDemand)}</b></div><div><small>20% 預留資料埠</small><b>${fmt(c.sparePorts)}</b></div><div><small>48 埠接入設備</small><b>${fmt(c.accessSwitches)}</b></div></div><p>${c.assumption}</p>`:architecturePage===1?`<div class="equipment-list">${p.equipment.map(e=>`<div><b>${e.label}</b><small>${e.model} · ${e.role==='access'?c.accessSwitches:e.role==='endpoint'?state.employees:e.role==='distribution'?Math.max(1,c.distributionPairs):1} 台／組</small></div>`).join('')}</div>`:`<p>${p.reasons.join(' ')}</p><p>${p.availability}</p><p>${state.scope}</p>${p.id==='three-tier'?`<p>${c.distributionAssumption} 規劃 ${c.distributionPairs} 組、${c.distributionSwitches} 台彙聚。</p>`:''}`}</div>`;$$('[data-arch-page]').forEach(b=>b.onclick=()=>{architecturePage=+b.dataset.archPage;renderData();});return;}
 if(view==='assets'){const filtered=state.assets.filter(a=>(a.id+' '+a.name+' '+a.model).toLowerCase().includes(assetQuery.toLowerCase())),navigation=pager(filtered.length,size);$('#data-view').innerHTML=`<div class="data-panel"><div class="data-title"><h2>資產與設備壽命</h2><span>PC 6 年 · 線材 15 年 · 網孔 20 年 · ${state.assets.length} 項資產</span></div><div class="data-tools"><input id="asset-search" aria-label="搜尋資產" placeholder="搜尋設備名稱、編號或型號" value="${esc(assetQuery)}"><div><button class="secondary" id="asset-practice">故障練習</button><button class="secondary" id="asset-day">快轉 1 日</button></div></div><div class="table-page"><table><thead><tr><th>資產／用途</th><th>型號</th><th>健康度</th><th>已用／預期年限</th><th>狀態</th><th></th></tr></thead><tbody>${filtered.slice(dataPage*size,(dataPage+1)*size).map(a=>`<tr><td>${esc(a.name)}<small>${a.id} · ${a.endpointCount} 位員工</small></td><td>${esc(a.model)}</td><td><div class="condition-meter"><progress max="100" value="${a.condition}"></progress>${a.condition.toFixed(0)}%</div></td><td>${S.formatAge(a.ageMinutes)} / ${S.formatAge(a.lifespanMinutes)}</td><td><span class="status-badge" data-status="${R.indicator(state,a.id,st).color}" title="${esc(faultName(a))}"><i></i>${R.indicator(state,a.id,st).color==='red'?'異常':'正常'}</span></td><td><button data-open-asset="${a.id}">直接管理 ↗</button></td></tr>`).join('')}</tbody></table>${!filtered.length?'<div class="empty">目前沒有符合的資產。</div>':''}</div>${navigation}</div>`;$('#asset-practice').onclick=showPractice;$('#asset-day').onclick=()=>act(()=>S.tick(state,1440));$('#asset-search').oninput=e=>{const pos=e.target.selectionStart;assetQuery=e.target.value;dataPage=0;renderData();$('#asset-search').focus();$('#asset-search').setSelectionRange(pos,pos);};bindPager();return;}
 const records=state.incidents.filter(i=>incidentHistory?i.resolved:!i.resolved).slice().reverse(),navigation=pager(records.length,2);$('#data-view').innerHTML=`<div class="data-panel"><div class="data-title"><h2>告警與工單</h2><div class="button-row"><button id="incident-filter" class="secondary">${incidentHistory?'查看待處理':'查看已處理'}</button><button class="secondary" id="incident-practice">故障練習</button><button class="secondary" id="incident-test">重新驗證</button></div></div><p>${st.message}</p><div class="incident-page">${records.length?records.slice(dataPage*2,dataPage*2+2).map(i=>incidentCard(i,incidentHistory)).join(''):'<div class="empty">目前沒有此類事件，可安排故障練習。</div>'}</div>${navigation}</div>`;$('#incident-filter').onclick=()=>{incidentHistory=!incidentHistory;dataPage=0;renderData();};$('#incident-practice').onclick=showPractice;$('#incident-test').onclick=testNetwork;bindPager();}
function incidentCard(i,resolved){return `<article class="incident-card ${resolved?'resolved':''}"><h3>${i.id} · ${esc(i.title)}</h3><p>設備 ${esc(i.assetId)} · ${i.source==='automatic'?'營運自動事件':'練習情境'} · ${resolved?'已處理':i.diagnosed?'已蒐證，等待處置':'尚未查明根因'}</p><p>${esc(i.evidence)}</p>${!resolved?`<div class="button-row"><button class="primary" data-open-asset="${i.assetId}">直接檢查設備 →</button></div>`:''}</article>`;}
function bindVisits(){$$('[data-open-asset]').forEach(b=>b.onclick=()=>selectAsset(b.dataset.openAsset));}
function faultName(a){return !a.fault?'正常':a.fault==='misplug'?'接錯網孔':a.fault==='oxidation'?'接點氧化／間歇':a.fault==='intermittent'?'線材間歇斷線':a.fault==='end-of-life'?'模型壽命耗盡':'硬體故障';}
function showPractice(){if(!state?.milestones.operating)return toast('先完成建置與驗收，營運後才開放故障情境。');dialog(`<span class="eyebrow">SAFE PRACTICE / SIMULATED INCIDENT</span><h2>讓一件真實狀態的異常發生。</h2><p>選擇後會真的影響教學網路的狀態，不會只是跳出說明。直接選取故障設備，蒐證、修復，再驗證。</p><div class="help-grid">${[['misplug','同仁亂插網路線','員工把網路線換到錯誤網孔／VLAN。'],['cable','網路線鬆動與彎折','測試間歇斷線，不能看到一次 UP 就當作修好。'],['jack','網孔氧化、接觸不良','接點會反覆 UP／DOWN，要先找出是哪個插座。'],['pc','電腦主機故障','換線不會修好主機硬體。'],['aging','模擬 6 年電腦到期','只將指定 PC 的使用年齡設為 6 年，便於維修練習；其他設備不會被加速老化。'],['switch','交換器故障','確認影響範圍；沒有設定自動切換的備機不會接手。']].map(([id,title,body])=>`<div><h3>${title}</h3><p>${body}</p><button class="secondary" data-inject="${id}">開始情境</button></div>`).join('')}</div>`);$$('[data-inject]').forEach(b=>b.onclick=()=>{const r=S.inject(state,b.dataset.inject);if(r.ok){$('#dialog').close();view='incidents';incidentHistory=false;dataPage=0;}toast(r.message);render();});}
function testNetwork(){const r=S.test(state),st=S.status(state);render();dialog(`<span class="eyebrow">WORKSTATION / ACCEPTANCE TEST</span><h2>${r.ok?'教學網路驗收 PASS':'驗收尚未通過'}</h2><div class="console-status">${esc(r.message)}</div><pre class="asset-evidence">${r.ok?`代表工作站 → 10.10.10.1\n模型連線檢查：通過\n規劃員工 ${fmt(st.total)} / 目前可用 ${fmt(st.online)}\n持續追蹤 ${st.sampledEndpoints} 個代表工作站的線材、網孔與主機。`:`模型連線／事件檢查：失敗\n${st.configurationProblems.join('\n')}\n受影響 ${st.affected} 人，${st.activeIncidents} 件未解決事件。`}</pre><p>這是狀態模型驗收，不是實際封包或完整 Cisco 協定引擎。所有故障需處理並再次驗證。</p><button class="primary" id="close-test">返回工作</button>`);$('#close-test').onclick=()=>$('#dialog').close();}
// Cisco-style CLI is shared with the field prototype; the company model validates its output.
function consoleKeys(){return state.planId==='small'?['access']:['core','access'];}
function initConsoles(){for(const id of consoleKeys()){if(!ui().consoles[id])ui().consoles[id]=C.create(id==='core'?'CORE-01':'ACCESS-01',Array.from({length:24},(_,i)=>'Gi1/0/'+(i+1)),{},id==='core');ui().consoleLogs[id]??=['USB Console / 9600 8N1\nCatalyst 風格教學指令子集。輸入 ? 查看目前模式。'];ui().demoIndex[id]??=0;}}
function commands(id){const small=state.planId==='small';return id==='core'?['enable','configure terminal','vlan 10','name OFFICE','exit','ip routing','interface vlan 10','ip address 10.10.10.1 255.255.255.0','no shutdown','exit','interface gi1/0/23','switchport mode access','switchport access vlan 10','no shutdown','exit','interface gi1/0/24','switchport mode trunk','switchport trunk allowed vlan 10','no shutdown','end']:['enable','configure terminal','vlan 10','name OFFICE','exit','interface gi1/0/1','switchport mode access','switchport access vlan 10','no shutdown','exit','interface gi1/0/24',small?'switchport mode access':'switchport mode trunk',small?'switchport access vlan 10':'switchport trunk allowed vlan 10','no shutdown','end'];}
function singleConsoleReady(id){const r=ui().consoles[id].running,u=r.interfaces['GigabitEthernet1/0/24'];if(!r.vlans[10]||!u||u.shutdown)return false;if(id==='core'){const edge=r.interfaces['GigabitEthernet1/0/23'];if(!edge||edge.shutdown||edge.mode!=='access'||edge.access!==10)return false;const s=r.interfaces.Vlan10;return !!s&&!s.shutdown&&s.address==='10.10.10.1'&&s.mask==='255.255.255.0'&&r.routing&&u.mode==='trunk'&&C.carries(u,10);}const a=r.interfaces['GigabitEthernet1/0/1'];return a&&!a.shutdown&&a.mode==='access'&&a.access===10&&(state.planId==='small'?u.mode==='access'&&u.access===10:u.mode==='trunk'&&C.carries(u,10));}
