function syncNetwork(){if(!state.milestones.cabled)return;const ready=consolesReady(),gateway=state.planId==='small'?ui().gateway:ui().consoles.core.running.interfaces.Vlan10?.address||'0.0.0.0';S.configure(state,{vlan:ready?10:1,trunk:state.planId==='small'?false:ready,gateway:C.validIP(gateway)?gateway:'0.0.0.0',dhcp:ui().dhcp});if(consoleKeys().every(id=>!C.dirty(ui().consoles[id]))&&configReady())S.saveConfig(state);}
