function point(x,y,z=0){return{x:(x-y)*.8,y:(x+y)*.4-z};}
function project(x,y,z=0){const p=point(x,y,z),c=point(camera.x,camera.y);return{x:width/2+(p.x-c.x)*zoom,y:height/2+(p.y-c.y)*zoom};}
function unproject(x,y){const c=point(camera.x,camera.y),a=(x-width/2)/zoom+c.x,b=(y-height/2)/zoom+c.y;return{x:(a/.8+b/.4)/2,y:(b/.4-a/.8)/2};}
function polygon(points,fill,stroke='#9cb6af22'){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
function floor(x,y,w,d,fill){polygon([point(x,y),point(x+w,y),point(x+w,y+d),point(x,y+d)],fill);}
function box(x,y,w,d,h,top,left,right,base=0){polygon([point(x,y+d,base),point(x+w,y+d,base),point(x+w,y+d,base+h),point(x,y+d,base+h)],left);polygon([point(x+w,y,base),point(x+w,y+d,base),point(x+w,y+d,base+h),point(x+w,y,base+h)],right);polygon([point(x,y,base+h),point(x+w,y,base+h),point(x+w,y+d,base+h),point(x,y+d,base+h)],top);}
function label(t,x,y,z,color='#d0e0cd',size=11){const p=point(x,y,z);ctx.font=`${size}px "Microsoft JhengHei",sans-serif`;ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText(t,p.x,p.y);}
function line(points,color,thickness=2,dash=[]){ctx.beginPath();points.forEach(([x,y,z],i)=>{const p=point(x,y,z);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)});ctx.strokeStyle=color;ctx.lineWidth=thickness;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([]);}
function lamp(x,y,z,bad,r=6/zoom){const p=point(x,y,z);ctx.save();ctx.fillStyle='#102332';ctx.beginPath();ctx.arc(p.x,p.y,r+2,0,Math.PI*2);ctx.fill();ctx.shadowColor=bad?'#ff3b48':'#21e58b';ctx.shadowBlur=9;ctx.fillStyle=bad?'#ff4654':'#21e58b';ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fill();ctx.restore();}
